const msg = $json.message || {};
const text = (msg.text || '').trim();
const chatId = msg.chat && msg.chat.id;
const userId = msg.from && msg.from.id;
const firstName = (msg.from && msg.from.first_name) || '';
const lastName = (msg.from && msg.from.last_name) || '';
const fullName = (firstName + ' ' + lastName).trim();

const lower = text.toLowerCase();
let command = 'help';
let rawOrder = '';
let idPedido = '';
let nuevoEstado = '';
let estadoValido = false;

if (lower === '/menu' || lower === 'menu' || lower === '/start') {
  command = 'menu';
} else if (lower === '/puntos' || lower === 'puntos' || lower === '4' || lower === 'ver mis puntos') {
  command = 'puntos';
} else if (lower.startsWith('/estado') || lower.startsWith('estado')) {
  command = 'estado';
  const body = text.replace(/^\/?estado/i, '').trim();
  const parts = body.split(/\s+/);
  idPedido = parts.shift() || '';
  nuevoEstado = parts.join(' ').trim();
  const validos = ['Recibido', 'Preparación', 'En camino', 'Entregado'];
  const norm = (s) => (s || '').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  const match = validos.find(v => norm(v) === norm(nuevoEstado));
  if (match) { nuevoEstado = match; estadoValido = true; }
} else if (lower.startsWith('/pedir') || lower.startsWith('pedir')) {
  command = 'pedir';
  rawOrder = text.replace(/^\/?pedir/i, '').trim();
}

const parsedItems = [];
if (command === 'pedir' && rawOrder) {
  for (const part of rawOrder.split(',')) {
    const seg = part.trim();
    if (!seg) continue;
    let qty = 1;
    let name = seg;
    const m1 = seg.match(/^(\d+)\s+(.+)$/);
    const m2 = seg.match(/^(.+?)\s*[xX]\s*(\d+)$/);
    if (m1) { qty = parseInt(m1[1], 10); name = m1[2].trim(); }
    else if (m2) { name = m2[1].trim(); qty = parseInt(m2[2], 10); }
    if (!qty || qty < 1) qty = 1;
    parsedItems.push({ nombre: name, cantidad: qty });
  }
}

return { json: { chatId, userId, fullName, text, command, rawOrder, parsedItems, idPedido, nuevoEstado, estadoValido } };

const menu = $input.all().map(i => i.json);
const chatId = $('Parse Command').first().json.chatId;
const money = (n) => '$' + Math.round(Number(n) || 0).toLocaleString('es-CO');

const cats = {};
for (const m of menu) {
  const cat = m.categoria || 'Otros';
  if (!cats[cat]) cats[cat] = [];
  cats[cat].push(m);
}

let text = '☕ *MENÚ DELIVERYBOT*\n\n';
for (const cat of Object.keys(cats)) {
  text += '*' + cat + '*\n';
  for (const m of cats[cat]) {
    const stock = Number(m.stock) || 0;
    const disp = stock > 0 ? '(' + stock + ' disp.)' : '(AGOTADO)';
    text += '• ' + m.nombre + ' - ' + money(m.precio) + ' ' + disp + '\n';
  }
  text += '\n';
}
text += 'Para pedir escribe: /pedir 2 cafe, 1 empanada';
text += '\n\n\u2b50 Opciones:\n1. Ver men\u00fa (/menu)\n2. Hacer pedido (/pedir)\n3. Estado (/estado)\n4. Ver mis Puntos (/puntos)';

return [{ json: { chatId, menuText: text } }];

const menu = $input.all().map(i => i.json);
const parse = $('Parse Command').first().json;
const ordered = parse.parsedItems || [];
const money = (n) => '$' + Math.round(Number(n) || 0).toLocaleString('es-CO');
const normalize = (s) => (s || '').toString().toLowerCase().trim().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

let ok = true;
const errors = [];
let total = 0;
const lines = [];
const stockUpdates = [];

if (ordered.length === 0) {
  ok = false;
  errors.push('No entendí los productos. Ejemplo: /pedir 2 cafe, 1 empanada');
}

for (const item of ordered) {
  const q = normalize(item.nombre);
  const match = menu.find(m => normalize(m.nombre) === q) || menu.find(m => normalize(m.nombre).includes(q));
  if (!match) { ok = false; errors.push('❌ "' + item.nombre + '" no está en el menú.'); continue; }
  const stock = Number(match.stock) || 0;
  const precio = Number(match.precio) || 0;
  if (stock < item.cantidad) { ok = false; errors.push('❌ Sin stock suficiente de ' + match.nombre + ' (disponible: ' + stock + ').'); continue; }
  const subtotal = precio * item.cantidad;
  total += subtotal;
  lines.push(item.cantidad + ' x ' + match.nombre + ' = ' + money(subtotal));
  stockUpdates.push({ id_producto: match.id_producto, stock: stock - item.cantidad });
}

const now = $now;
const fecha = now.toFormat('yyyy-MM-dd');
const hora = now.toFormat('HH:mm:ss');
const idPedido = 'ORD-' + now.toFormat('yyyyMMdd-HHmmss') + '-' + Math.floor(Math.random() * 900 + 100);

return [{ json: {
  ok,
  error: errors.join('\n'),
  id_pedido: idPedido,
  id_usuario: parse.userId,
  chatId: parse.chatId,
  nombre: parse.fullName,
  detalles_pedido: lines.join(' | '),
  resumen: lines.join('\n'),
  total_pago: Number(total.toFixed(2)),
  total_fmt: money(total),
  estado: 'Recibido',
  fecha,
  hora,
  stockUpdates,
} }];

const v = $('Validar Pedido y Calcular Total').item.json;
const rows = $input.all().map(i => i.json).filter(r => r && r.telegram_id);
const prev = rows[0];
const prevPts = prev ? (Number(prev.puntos_lealtad) || 0) : 0;
// 1 punto de lealtad por cada $1.000 gastados
const ganados = Math.floor((Number(v.total_pago) || 0) / 1000);
const departamento = (prev && prev.departamento) ? prev.departamento : '';

return [{ json: {
  telegram_id: String(v.id_usuario),
  nombre_completo: v.nombre || (prev ? prev.nombre_completo : ''),
  departamento,
  puntos_lealtad: prevPts + ganados
} }];

