const parse = $('Parse Command').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.id_pedido);
const pedido = rows[0];
const encontrado = !!pedido;
const emojis = { 'Recibido': '📥', 'Preparación': '👨‍🍳', 'En camino': '🛵', 'Entregado': '✅' };
const estado = parse.nuevoEstado;

return [{ json: {
  ok: encontrado && parse.estadoValido,
  encontrado,
  estadoValido: parse.estadoValido,
  adminChatId: String(parse.chatId),
  id_pedido: parse.idPedido,
  nuevoEstado: estado,
  emoji: emojis[estado] || '🔔',
  clienteChatId: pedido ? String(pedido.id_usuario) : '',
  detalles: pedido ? pedido.detalles_pedido : '',
