const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0 && r.id_pedido);
const hoy = $now.toFormat('yyyy-MM-dd');
const money = (n) => '$' + Math.round(Number(n) || 0).toLocaleString('es-CO');

// Solo pedidos de hoy
const delDia = rows.filter(r => String(r.fecha) === hoy);

let totalVendido = 0;
const porProducto = {};
const porHora = {};

for (const r of delDia) {
  totalVendido += Number(r.total_pago) || 0;
  const h = (String(r.hora || '').split(':')[0] || '00').padStart(2, '0');
  porHora[h] = (porHora[h] || 0) + 1;
  const partes = String(r.detalles_pedido || '').split('|');
  for (const p of partes) {
    const m = p.trim().match(/^(\d+)\s*x\s*(.+?)\s*=/i);
    if (m) {
      const qty = parseInt(m[1], 10) || 0;
      const nombre = m[2].trim();
      porProducto[nombre] = (porProducto[nombre] || 0) + qty;
    }
  }
}

let estrella = '—', estrellaQty = 0;
for (const [nombre, qty] of Object.entries(porProducto)) {
  if (qty > estrellaQty) { estrella = nombre; estrellaQty = qty; }
}

let horaPico = '—', horaPicoQty = 0;
for (const [h, qty] of Object.entries(porHora)) {
  if (qty > horaPicoQty) { horaPico = h + ':00'; horaPicoQty = qty; }
}

let text = '📊 *REPORTE DIARIO DE VENTAS*\n' + hoy + '\n\n';
text += '🧾 Pedidos: ' + delDia.length + '\n';
text += '💰 Total vendido: ' + money(totalVendido) + '\n';
text += '⭐ Producto estrella: ' + estrella + (estrellaQty ? ' (' + estrellaQty + ' uds.)' : '') + '\n';
text += '⏰ Hora pico: ' + horaPico + (horaPicoQty ? ' (' + horaPicoQty + ' pedidos)' : '');

if (delDia.length === 0) {
  text = '📊 *REPORTE DIARIO DE VENTAS*\n' + hoy + '\n\nHoy no se registraron pedidos.';
}

// Destino del reporte: el mismo chat del último pedido registrado (un solo bot/chat)
let chatId = '';
for (const r of rows) {
  if (r.id_usuario) chatId = String(r.id_usuario);
}

return [{ json: {
  reporte: text,
  chatId,
  fecha: hoy,
  pedidos: delDia.length,
  total_vendido: totalVendido,
  producto_estrella: estrella,
  hora_pico: horaPico,
} }];

const calc = $('Calcular Puntos').item.json;
const rows = $input.all().map(i => i.json).filter(r => r && r.telegram_id);
const prev = rows[0];
const prevPts = prev ? (Number(prev.puntos_lealtad) || 0) : 0;
const ganados = Number(calc.puntos_ganados) || 0;
return [{ json: {
  telegram_id: String(calc.telegram_id),
  nombre_completo: (prev && prev.nombre_completo) ? prev.nombre_completo : calc.nombre,
  puntos_lealtad: prevPts + ganados,
} }];

const parse = $('Parse Command').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.telegram_id);
const prev = rows[0];
const pts = prev ? (Number(prev.puntos_lealtad) || 0) : 0;
const nombre = parse.fullName || (prev ? prev.nombre_completo : '') || 'cliente';
const text = 'Hola ' + nombre + ', actualmente tienes \ud83c\udfc6 ' + pts + ' puntos acumulados. \u00a1Sigue comprando para canjear premios!';
return [{ json: { chatId: parse.chatId, mensaje: text } }];
